import { Schema } from 'effect'
import { HttpApi, HttpApiEndpoint, HttpApiGroup, OpenApi } from 'effect/unstable/httpapi'
import {
  HARBOR_OPENAPI_ALIAS_PATH,
  HARBOR_OPENAPI_PATH,
  HARBOR_OPENAPI_VERSION,
  harborProtocolOperations,
  type HarborProtocolOperation,
} from './openapi'

const operationById = new Map<string, HarborProtocolOperation>(
  harborProtocolOperations.map((operation) => [operation.operationId, operation])
)

function operationAnnotations(
  operationId: (typeof harborProtocolOperations)[number]['operationId']
) {
  const operation = operationById.get(operationId)
  return OpenApi.annotations({
    identifier: operationId,
    summary: operation?.summary,
    description: operation?.description,
  })
}

