export const HarborHttpApi = HttpApi.make('HarborApi')
  .annotateMerge(
    OpenApi.annotations({
      title: 'Harbor API',
      version: HARBOR_OPENAPI_VERSION,
      description: 'First-party Harbor control-plane and runtime ingress contract.',
      servers: [
        { url: 'https://api.tryharbor.ai', description: 'Production' },
        { url: 'https://stagapi.tryharbor.ai', description: 'Staging' },
      ],
    })
  )
  .add(DiscoveryGroup, HealthGroup, WorkspacesGroup, RuntimeGroup, TriggersGroup)

export interface HarborEffectOpenApiOptions {
  readonly servers?: ReadonlyArray<OpenApi.OpenAPISpecServer> | undefined
}

export function createHarborEffectOpenApiDocument(options: HarborEffectOpenApiOptions = {}) {
  const api = options.servers
    ? HarborHttpApi.annotateMerge(OpenApi.annotations({ servers: options.servers }))
    : HarborHttpApi
  return OpenApi.fromApi(api)
}

export interface HarborHttpApiOperation {
  readonly operationId: string
  readonly method: string
  readonly path: string
  readonly group: string
}

export function collectHarborHttpApiOperations(): readonly HarborHttpApiOperation[] {
  const operations: HarborHttpApiOperation[] = []
  HttpApi.reflect(HarborHttpApi, {
    onGroup: () => {},
    onEndpoint: ({ group, endpoint }) => {
      operations.push({
        operationId: endpoint.name,
        method: endpoint.method.toLowerCase(),
        path: endpoint.path,
        group: group.identifier,
      })
    },
  })
  return operations.sort((a, b) => a.operationId.localeCompare(b.operationId))
}

export function assertHarborHttpApiMatchesOperationRegistry(): void {
  const httpApiOperations = collectHarborHttpApiOperations()
  const registryOperations = [...harborProtocolOperations]
    .map((operation) => ({
      operationId: operation.operationId,
      method: operation.method,
      path: operation.path,
    }))
    .sort((a, b) => a.operationId.localeCompare(b.operationId))

  if (httpApiOperations.length !== registryOperations.length) {
    throw new Error(
      `Harbor HttpApi operation count mismatch: httpapi=${httpApiOperations.length} registry=${registryOperations.length}`
    )
  }

  for (let index = 0; index < registryOperations.length; index += 1) {
    const httpApi = httpApiOperations[index]
    const registry = registryOperations[index]
    if (!httpApi || !registry) throw new Error('Harbor HttpApi registry comparison failed')
    if (
      httpApi.operationId !== registry.operationId ||
      httpApi.method !== registry.method ||
      httpApi.path !== registry.path
    ) {
      throw new Error(
        `Harbor HttpApi operation mismatch at ${index}: httpapi=${httpApi.operationId} ${httpApi.method} ${httpApi.path}, registry=${registry.operationId} ${registry.method} ${registry.path}`
      )
    }
  }
}
